export const CONNECTOR_TYPES = ['Zoho-based services', 'Other services', 'Web3'] as const;

export type ConnectorTypeFilter = (typeof CONNECTOR_TYPES)[number];

/** URL slug for /connectors/[slug]: lowercase, non-alphanumerics to dashes. */
export function connectorSlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
